from lib import *
from event import *

def visao_body(status='PUBLICADO', banner_=''):
  nums = stats([('Itens', '14', '', 'ne', 'W-Event-Programacao.dc.html'), ('Em rascunho', '1', 'RASCUNHO', 'dr', 'W-Event-Programacao.dc.html'), ('Cancelados', '1', 'CANCELADO', 'ca', 'W-Event-Programacao.dc.html'), ('Fora do período', '1', 'FORA', 'ne', 'W-Event-Programacao.dc.html'), ('Participants', '24', '', 'ne', 'W-Event-Participants.dc.html')])
  det = card(h2('Detalhes', btn('Editar', 'ghost', 32, href='W-Event-Editar.dc.html')) + dl([('Onde', 'Manaus, AM'), ('Período', 'sex 20 a dom 22 de nov. de 2026'), ('Fuso', 'Horário de Manaus (UTC−4)'), ('Estado', badge(status, BK.get(status, 'ok'))), ('Participants', 'Vêm de todos os Group members, 7 tirados'), ('Criado por', 'Bruno Reis, em 12 de out.')]))
  nxt = card(h2('Destaques no Resumo', '<a href="W-Event-Resumo.dc.html" style="font-size: 14px; font-weight: 600; text-decoration: none">Ver o Resumo</a>') + ''.join(f'<div style="display: grid; grid-template-columns: 110px 1fr auto; gap: 12px; align-items: center; font-size: 14px; padding: 6px 0; border-top: 1px solid $sf2"><span style="{MONO}; color: $mu">{d}</span><span style="font-weight: 600">{n}</span>{ico(I_STAR, 16, "1.8", "$ev5")}</div>' for d, n in [('geral', 'Hospedagem'), ('sex 08:10', 'Voo VIX → MAO'), ('sáb 19:00', 'Show'), ('dom 00:40', 'Translado de volta')]), gap=8)
  feed = card(h2('Mudanças recentes') + ''.join(f'<div style="display: flex; gap: 10px; align-items: flex-start; font-size: 14px">{av(i, size=28)}<span style="line-height: 1.4"><strong>{w}</strong> {t}<br><span style="font-size: 12px; color: $mu">{q}</span></span></div>' for i, w, t, q in [('CD', 'Carla', 'criou Desmontagem como rascunho', 'há 20 min'), ('BR', 'Bruno', 'mudou a hora de Passagem de som de 15:00 para 16:00', 'há 2 h'), ('BR', 'Bruno', 'trocou Jacque do Carro 1 para o Carro 2', 'há 2 h'), ('BR', 'Bruno', 'cancelou Entrevista na rádio', 'ontem'), ('CD', 'Carla', 'tirou 2 pessoas dos Participants', 'ontem')]))
  teams = card(h2('Participants por Team', '<a href="W-Event-Participants.dc.html" style="font-size: 14px; font-weight: 600; text-decoration: none">Gerenciar</a>') + '<div style="display: flex; flex-wrap: wrap; gap: 8px">' + ''.join(chip(t, n, h=36) for t, n in [('Cantores', '10/12'), ('Banda', '7/8'), ('Técnica', '4/6'), ('Produção', '3/5')]) + '</div><span style="font-size: 13px; color: $mu">Fora: Paulo, Rafa e mais 5. Nenhum Participant sem Team.</span>', gap=10)
  info = card(h2('Informações gerais', btn('+ Item', 'ghost', 32, href='W-Event-ItemEditar.dc.html'), dot=True) + ''.join(f'<a href="W-Event-Item.dc.html" style="text-decoration: none; color: $tx; display: flex; flex-direction: column; padding: 8px 0; border-top: 1px solid $sf2"><span style="font-size: 15px; font-weight: 600">{n}</span><span style="font-size: 13px; color: $mu">{s}</span></a>' for n, s in [('Hospedagem', 'Hotel Taj Mahal, quartos por Team'), ('Contatos da produção', 'Bruno, Carla e motoristas')]), gap=6)
  return banner_ + nums + f'<div style="display: flex; flex-wrap: wrap; gap: 14px; align-items: flex-start"><div style="flex: 999 1 480px; min-width: 0; display: flex; flex-direction: column; gap: 14px">{det}{nxt}{info}</div><div style="flex: 1 1 340px; max-width: 460px; display: flex; flex-direction: column; gap: 14px">{feed}{teams}</div></div>'

ITEM_PANEL = f'''<span style="font-size: 15px; font-weight: 600; color: $evT">Dom 22/11, 00:40 <span style="font-weight: 400; color: $mu">horário de Manaus</span></span>
{dl([("Local", "Teatro Amazonas → Hotel Taj Mahal"), ("Obs", "Despachar o som no Carro 2"), ("Quem vê", "Todos os Participants"), ("Estado", "Publicado"), ("No Resumo", "Sim, como destaque")], 96)}
<div style="border: 1px solid $bd; border-radius: 16px; overflow: hidden">
<div style="padding: 10px 14px; background: $sf2; display: flex; justify-content: space-between; align-items: center; font-size: 13px; font-weight: 600"><span>Carros <span style="font-weight: 400; color: $mu">cada um no seu</span></span><a href="W-Event-FieldPessoas.dc.html" style="font-size: 13px; text-decoration: none">Editar</a></div>
{"".join(f'<div style="padding: 10px 14px; border-top: 1px solid $bd; display: grid; grid-template-columns: 110px 1fr auto; gap: 10px; align-items: center; font-size: 14px"><span style="font-weight: 600">{n}</span><span style="color: $mu; white-space: nowrap; overflow: hidden; text-overflow: ellipsis">{p}</span><span style="{MONO}; font-size: 13px; color: $mu">{k}</span></div>' for n, p, k in [("Carro 1 - EC", "Matias (dirige), Lu, Alice, Tiago, Bruno", "5"), ("Carro 2", "Rafa (dirige), Jacque, Paulo, Carla, som", "5"), ("Van Técnica", "Diego (dirige), Técnica", "4")])}
</div>
<div style="display: flex; flex-direction: column; gap: 8px"><span style="font-size: 13px; font-weight: 600; color: $mu">Personal notes</span>{"".join(f'<div style="display: flex; gap: 10px; align-items: flex-start; font-size: 14px">{av(i, t, 28)}<span><strong>{n}</strong> {x}</span></div>' for i, t, n, x in [("LU", "Cantores", "Lu", "Volto com a mala de figurino"), ("MA", "Banda", "Matias", "Posso levar mais um no Carro 1")])}</div>
<span style="font-size: 12px; color: $mu">Alterado por Bruno Reis há 2 h</span>'''

def item_top():
  return btn('Editar', 'pri', 36, href='W-Event-ItemEditar.dc.html') + iconbtn('⋯', 'Ações do item')

def build():
  add('W-Event-Visao', 'Event · Visão geral', shell(ev_header('Visão geral') + visao_body(), 'events'), 1260)
  add('W-Event-Programacao', 'Event · Programação (lista)', shell(ev_header('Programação') + prog_toolbar() + prog_table(), 'events'), 1260)
  add('W-Event-Acoes', 'Event · Programação · Ações do item', shell(ev_header('Programação') + prog_toolbar() + prog_table(menu_on='Passagem de som'), 'events'), 1260)
  add('W-Event-Timeline', 'Event · Timeline (dias)', shell(ev_header('Timeline') + timeline_cols() + '<span style="font-size: 13px; color: $mu">Clique num item para abrir o painel. Botão direito ou “⋯” para as ações.</span>', 'events'), 1100)
  add('W-Event-Item', 'Event · item (painel)', shell(ev_header('Programação') + prog_compact('Translado de volta'), 'events', panel=panel('Translado de volta', ITEM_PANEL, top=item_top(), ctx='Dom 22 · Saída Manaus')), 1500)

  form = f'''<div style="display: flex; flex-direction: column; gap: 12px">
{field("Nome", "Passagem de som", focus=True)}
<div style="display: grid; grid-template-columns: 1.3fr 1fr; gap: 12px">{select("Dia", "Sáb 21/11")}{field("Hora", "16:00", mono=True)}</div>
<label style="display: flex; align-items: center; gap: 10px; font-size: 14px">{checkbox(False, "Sem hora")}Sem hora (a definir)</label>
{select("Fuso", "Do Event: horário de Manaus")}
{field("Local", "Teatro Amazonas")}
{field("Obs", "Chegar 15:45")}
<a href="W-Event-QuemVe.dc.html" style="text-decoration: none; color: $tx; border: 1.5px solid $bd2; border-radius: 14px; padding: 10px 14px; display: flex; align-items: center; gap: 8px"><span style="flex-grow: 1; display: flex; flex-direction: column"><span style="font-size: 12px; font-weight: 600; color: $mu">Quem vê</span><span style="display: flex; gap: 6px; margin-top: 4px">{chip("Banda")}{chip("Técnica")}</span></span><span style="color: $mu; font-size: 18px">›</span></a>
<a href="W-Event-FieldPessoas.dc.html" style="text-decoration: none; color: $tx; border: 1.5px solid $bd2; border-radius: 14px; padding: 10px 14px; display: flex; align-items: center; gap: 8px"><span style="flex-grow: 1; display: flex; flex-direction: column"><span style="font-size: 12px; font-weight: 600; color: $mu">Fields de pessoas</span><span style="font-size: 15px">Nenhum ainda</span></span><span style="color: $lk; font-size: 14px; font-weight: 600">+ Field</span></a>
<label style="display: flex; align-items: center; gap: 10px; font-size: 14px">{checkbox(False, "Destacar no Resumo")}Destacar no Resumo</label>
<div style="display: flex; flex-direction: column; gap: 6px"><span style="font-size: 13px; font-weight: 600; color: $mu">Estado</span>{seg(["Rascunho", "Publicado"], 1)}</div>
</div>'''
  add('W-Event-ItemEditar', 'Event · criar ou editar item (painel)', shell(ev_header('Programação') + prog_compact('Passagem de som'), 'events', panel=panel('Editar item', form, foot=btn('Cancelar', 'out', href='W-Event-Item.dc.html') + btn('Salvar', 'pri', href='W-Event-Item.dc.html'), ctx='Sáb 21 · Saída Manaus')), 1500)

  def grp(n, ppl, drv):
    chips = ''.join(f'<span style="height: 32px; padding: 0 10px 0 4px; border-radius: 16px; background: $sf2; font-size: 13px; display: inline-flex; align-items: center; gap: 6px">{av(i, t, 24)}{p}{" (dirige)" if p == drv else ""} <button aria-label="Tirar {p}" style="border: 0; background: transparent; color: $mu; font: inherit; font-size: 14px; padding: 0">×</button></span>' for i, t, p in ppl)
    return f'<div style="border: 1px solid $bd; border-radius: 16px; padding: 12px; display: flex; flex-direction: column; gap: 10px"><div style="display: flex; align-items: center; gap: 8px"><input value="{n}" aria-label="Nome do grupo" style="flex-grow: 1; border: 0; background: transparent; color: $tx; font: inherit; font-size: 15px; font-weight: 700; outline: none"><span style="{MONO}; font-size: 12px; color: $mu">{len(ppl)}</span>{iconbtn("⋯", "Ações do grupo", 30, False)}</div><div style="display: flex; flex-wrap: wrap; gap: 6px">{chips}<button style="height: 32px; padding: 0 12px; border-radius: 16px; border: 1.5px dashed $bd2; background: transparent; color: $lk; font: inherit; font-size: 13px; font-weight: 600">+ pessoa</button></div></div>'
  fp = f'''{field("Nome do Field", "Carros")}
<div style="display: flex; flex-direction: column; gap: 6px"><span style="font-size: 13px; font-weight: 600; color: $mu">Como as pessoas aparecem</span>{seg(["Cada um a sua", "Todos no item"], 0)}<span style="font-size: 12px; color: $mu">Cada um a sua: cada Participant vê só o grupo dele em destaque, com “Ver todos”.</span></div>
{grp("Carro 1 - EC", [("MA", "Banda", "Matias"), ("LU", "Cantores", "Lu"), ("AL", "Cantores", "Alice"), ("TS", "Banda", "Tiago"), ("BR", "Produção", "Bruno")], "Matias")}
{grp("Carro 2", [("RA", "Técnica", "Rafa"), ("JA", "Cantores", "Jacque"), ("PM", "Técnica", "Paulo"), ("CD", "Produção", "Carla")], "Rafa")}
{grp("Van Técnica", [("DI", "Técnica", "Diego")], "Diego")}
{btn("+ Grupo", "out", 36, extra="align-self: flex-start")}
<div style="background: $drB; color: $drT; border-radius: 14px; padding: 10px 14px; font-size: 13px">10 Participants ainda sem grupo. <a href="#" style="color: $drT; font-weight: 600">Ver quem</a></div>'''
  add('W-Event-FieldPessoas', 'Event · Field de pessoas (subpasso)', shell(ev_header('Programação') + prog_compact('Translado de volta'), 'events', panel=panel('Field de pessoas', fp, back='W-Event-ItemEditar.dc.html', foot=btn('Apagar Field', 'dan') + '<span style="flex-grow: 1"></span>' + btn('Concluir', 'pri', href='W-Event-ItemEditar.dc.html'))), 1500)

  qv = f'''<label style="border: 1.5px solid $bd2; border-radius: 16px; padding: 12px 14px; display: flex; gap: 12px; align-items: center"><input type="radio" name="q" style="width: 20px; height: 20px; accent-color: $ac; margin: 0"><span style="display: flex; flex-direction: column"><span style="font-size: 15px; font-weight: 600">Todos os Participants</span><span style="font-size: 12px; color: $mu">24 pessoas</span></span></label>
<label style="border: 1.5px solid $ac; border-radius: 16px; padding: 12px 14px; display: flex; gap: 12px; align-items: flex-start"><input type="radio" name="q" checked style="width: 20px; height: 20px; accent-color: $ac; margin: 0"><span style="display: flex; flex-direction: column; gap: 8px"><span style="font-size: 15px; font-weight: 600">Teams</span><span style="display: flex; gap: 6px; flex-wrap: wrap">{chip("Cantores", h=34)}{chip("Banda", sel=True, h=34)}{chip("Técnica", sel=True, h=34)}{chip("Produção", h=34)}</span><span style="font-size: 12px; color: $mu">11 Participants veem este item</span></span></label>
<label style="border: 1.5px solid $bd2; border-radius: 16px; padding: 12px 14px; display: flex; gap: 12px; align-items: center"><input type="radio" name="q" style="width: 20px; height: 20px; accent-color: $ac; margin: 0"><span style="display: flex; flex-direction: column"><span style="font-size: 15px; font-weight: 600">Pessoas escolhidas</span><span style="font-size: 12px; color: $mu">Marque nome a nome</span></span></label>
<span style="font-size: 13px; color: $mu">A produção vê todos os itens. Quem está num Field de pessoas do item também vê.</span>'''
  add('W-Event-QuemVe', 'Event · Quem vê (subpasso)', shell(ev_header('Programação') + prog_compact('Passagem de som'), 'events', panel=panel('Quem vê', qv, back='W-Event-ItemEditar.dc.html', foot=btn('Concluir', 'pri', href='W-Event-ItemEditar.dc.html'))), 1500)

  # Ordenar
  rows = []
  for t, n, mv in [('sem hora', 'Almoço', True), ('10:00', 'Entrevista na rádio', False), ('16:00', 'Passagem de som', False), ('19:00', 'Show', True), ('19:00', 'Transmissão ao vivo', True), ('21:30', 'Desmontagem', False)]:
    hd = f'<span style="color: $lk; cursor: grab">{ico(I_GRIP, 18)}</span>' if mv else f'<span style="color: $mu2">{ico(I_LOCK, 16)}</span>'
    st = 'background: $sf; border: 1.5px solid $ac;' if n == 'Transmissão ao vivo' else ('background: $sf; border: 1px solid $bd;' if mv else 'background: $sf2; border: 1px solid transparent; opacity: 0.65;')
    rows.append(f'<div style="display: grid; grid-template-columns: 28px 76px 1fr auto; gap: 12px; align-items: center; padding: 10px 14px; border-radius: 14px; {st}">{hd}<span style="{MONO}; font-size: 14px">{t}</span><span style="font-size: 15px; font-weight: 600">{n}</span><span style="font-size: 12px; color: $mu">{"pode mover" if mv else "fixo pela hora"}</span></div>')
  ordb = card(h2('Sáb 21/11 · ordem manual', btn('Cancelar', 'out', 36, href='W-Event-Programacao.dc.html') + btn('Salvar ordem', 'pri', 36, href='W-Event-Programacao.dc.html'), dot=True) + banner('Arraste os itens sem hora e os que têm a mesma hora. Os outros ficam na ordem da hora.', 'ac') + '<div style="display: flex; flex-direction: column; gap: 8px">' + ''.join(rows) + '</div>')
  add('W-Event-Ordenar', 'Event · Ordenar (modo)', shell(ev_header('Programação') + ordb + prog_table(only={'dom'}), 'events'), 1100)

  # Resumo (como o Participant vê)
  hl = lambda n, w, s, big=False: f'<div style="border-radius: 20px; padding: 16px; display: flex; flex-direction: column; gap: 4px; {"background: " + EV["cover"] + "; color: #FFFFFF; grid-column: span 2; min-height: 150px; justify-content: flex-end" if big else "background: $sf; border: 1px solid $bd"}"><span style="font-size: 13px; {"color: #EDE5FE" if big else "color: $evT; font-weight: 600"}">{w}</span><span style="font-size: {26 if big else 18}px; font-weight: 700">{n}</span><span style="font-size: 13px; {"color: #EDE5FE" if big else "color: $mu"}">{s}</span></div>'
  res = banner('Assim os Participants veem o Resumo. Os destaques são os itens marcados com “Destacar no Resumo”.', 'ac', btn('Escolher destaques', 'out', 34, href='W-Event-Programacao.dc.html'))
  res += f'<div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 12px">{hl("Show", "sáb 21, 19:00", "Teatro Amazonas · figurino azul · chegar 18:00", True)}{hl("Voo VIX → MAO", "sex 20, 08:10 (Vitória)", "Chega 13:20 · QX7P2M")}{hl("Translado de volta", "dom 22, 00:40", "Carros · cada um vê o seu")}{hl("Hospedagem", "Informação geral", "Hotel Taj Mahal, quartos por Team")}</div>'
  res += card(h2('Onde e quando') + dl([('Onde', 'Manaus, AM'), ('Quando', 'sex 20 a dom 22 de nov.'), ('Fuso', 'Cada hora é a do lugar onde o item acontece'), ('Quem vai', '24 pessoas de 4 Teams')]))
  add('W-Event-Resumo', 'Event · Resumo (como o Participant vê)', shell(ev_header('Resumo') + res, 'events'), 1000)

  # Participants
  def parts(pending=False):
    data = [('LU', 'Lu Andrade', ['Cantores'], 'VIEWER', 'Carros, Quartos', True, False), ('JA', 'Jacque Lima', ['Cantores', 'Banda'], 'VIEWER', 'Carros, Quartos', not pending, pending), ('MA', 'Matias Rocha', ['Banda'], 'VIEWER', 'Carros', True, False), ('TS', 'Tiago Souza', ['Banda'], 'VIEWER', 'Carros', True, False), ('DI', 'Diego Pires', ['Técnica'], 'VIEWER', 'Carros', True, False), ('PM', 'Paulo Mendes', ['Técnica'], 'VIEWER', '', pending, pending), ('RA', 'Rafa Teixeira', ['Técnica'], 'VIEWER', '', pending, pending), ('AL', 'Alice Monteiro', ['Cantores'], 'VIEWER', 'Quartos', True, False), ('BR', 'Bruno Reis', ['Produção'], 'OWNER', 'Carros', True, False), ('CD', 'Carla Dias', ['Produção'], 'OWNER', '', pending, pending)]
    cols = 'grid-template-columns: 40px minmax(200px, 1.4fr) minmax(160px, 1fr) 100px minmax(160px, 1fr)'
    out = [f'<div role="row" style="display: grid; {cols}; gap: 12px; padding: 10px 16px; background: $sf2; font-size: 12px; font-weight: 600; color: $mu"><span role="columnheader">Vai</span><span role="columnheader">Pessoa</span><span role="columnheader">Teams</span><span role="columnheader">Papel</span><span role="columnheader">Nos Fields de pessoas</span></div>']
    for i, n, ts, r, f, on, ch in data:
      bg = ' background: $acs;' if ch else ''
      out.append(f'<label role="row" style="display: grid; {cols}; gap: 12px; align-items: center; padding: 0 16px; height: 52px; border-top: 1px solid $sf2;{bg}">{checkbox(on, "Vai: " + n)}<span style="display: flex; align-items: center; gap: 10px">{av(i, ts[0], 30)}<span style="font-size: 15px; font-weight: 600">{n}</span></span><span style="display: flex; gap: 4px; flex-wrap: wrap">{"".join(chip(x) for x in ts)}</span><span>{badge(r, "ac" if r == "OWNER" else "ne")}</span><span style="font-size: 13px; color: $mu">{f or "nenhum"}</span></label>')
    tb = f'<div style="display: flex; flex-wrap: wrap; gap: 10px; align-items: center">{searchbox("Buscar pessoa")}<span style="font-size: 13px; color: $mu">Marcar Team inteiro:</span>{chip("Cantores", "10/12", h=34)}{chip("Banda", "7/8", h=34)}{chip("Técnica", "4/6" if not pending else "6/6", sel=pending, h=34)}{chip("Produção", "3/5" if not pending else "4/5", h=34)}<span style="flex-grow: 1"></span>{filt("Todos", True)}{filt("Vão")}{filt("Não vão")}</div>'
    tbl = f'<div style="background: $sf; border-radius: 24px; padding: 4px; overflow-x: auto"><div role="table" aria-label="Participants" style="min-width: 760px; border-radius: 20px; overflow: hidden">{"".join(out)}</div></div>'
    bar = f'<div role="status" style="position: sticky; bottom: 16px; background: $inv; color: $invT; border-radius: 22px; padding: 12px 14px 12px 20px; display: flex; flex-wrap: wrap; align-items: center; gap: 12px; box-shadow: 0 20px 40px -20px rgba(0,0,0,0.5)"><span style="flex: 1 1 300px; font-size: 15px"><strong style="{MONO}">+3 · −1</strong> &nbsp;Entram Paulo, Rafa e Carla. Jacque sai e deixa 2 Fields de pessoas (Carros, Quartos).</span>{btn("Descartar", "out", 38)}{btn("Salvar", "pri", 38)}</div>' if pending else ''
    return shell(ev_header('Participants') + tb + tbl + bar, 'events')
  add('W-Event-Participants', 'Event · Participants', parts(), 1000)
  add('W-Event-ParticipantsSalvar', 'Event · Participants com mudanças', parts(True), 1000)

  # Editar Event, Draft, Cancelar, Cancelado, Vazio
  edf = '<div style="display: flex; flex-direction: column; gap: 12px">' + field('Nome', 'Saída Manaus') + field('Onde', 'Manaus, AM') + select('Fuso', 'Horário de Manaus (UTC−4)') + '<div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px">' + field('Começa', '20/11/2026', mono=True) + field('Termina', '22/11/2026', mono=True) + '</div>' + banner('Encurtar o período deixa 1 item fora do período. Ele continua lá, com o selo.', 'dr') + '</div>'
  add('W-Event-Editar', 'Event · editar (painel)', shell(ev_header('Visão geral') + visao_body(), 'events', panel=panel('Editar Event', edf, foot=btn('Cancelar', 'out', href='W-Event-Visao.dc.html') + btn('Salvar', 'pri', href='W-Event-Visao.dc.html'), ctx='Saída Manaus')), 1260)

  nat = dict(name='Natal na Praça', cover='linear-gradient(135deg, #52170C, #EF5A3C)', place='Praça Costa Pereira, Vitória', period='sáb 12 de dez. de 2026', tz='horário de Vitória (UTC−3)')
  dact = btn('Editar Event', 'sec', href='W-Event-Editar.dc.html') + btn('Apagar', 'dan') + btn('Publicar', 'pri')
  drb = banner('Este Event está em rascunho: só a produção vê. Ao publicar, os 20 Participants passam a ver o Resumo e a programação.', 'dr', btn('Publicar', 'pri', 34))
  draft_list = card(h2('Programação', btn('+ Item', 'pri', 34, href='W-Event-ItemEditar.dc.html'), dot=True) + ''.join(f'<div style="display: grid; grid-template-columns: 64px 1fr auto; gap: 12px; align-items: center; padding: 8px 0; border-top: 1px solid $sf2"><span style="{MONO}; font-size: 14px">{t}</span><span style="font-size: 15px; font-weight: 600">{n}</span>{badge(s, BK[s], True) if s else ""}</div>' for t, n, s in [('15:00', 'Concentração na sede', ''), ('18:00', 'Passagem de som', ''), ('20:00', 'Apresentação', 'RASCUNHO')]))
  add('W-Event-Rascunho', 'Event em Draft (Owner)', shell(ev_header('Visão geral', status='RASCUNHO', actions=dact, **nat) + drb + draft_list, 'events'), 1000)

  add('W-Event-CancelarConfirma', 'Event · confirmar cancelamento', shell(ev_header('Visão geral') + visao_body(), 'events', overlay=scrim_dialog('Cancelar Saída Manaus?', 'Os 24 Participants passam a ver o Event com o selo CANCELADO e a programação congelada. Nada é apagado, e dá para descancelar depois.', btn('Voltar', 'out', href='W-Event-Visao.dc.html') + btn('Cancelar Event', 'danf', href='W-Event-Cancelado.dc.html'))), 1260)

  fest = dict(name='Festival de Verão', cover='linear-gradient(135deg, #023538, #069FA6)', place='Vila Velha, ES', period='sáb 28 de nov. de 2026', tz='horário de Vitória (UTC−3)')
